/// <summary>
/// Sats at a swap's VHTLC by state. Mirrors
/// `lendaswap_sdk::arkade::VhtlcBalance` (TypeScript `VhtlcAmounts`).
/// </summary>
/// <param name="spendable_sats">
/// Spendable by an offchain transaction.
/// </param>
/// <param name="recoverable_sats">
/// Expired outputs that only [`SatoraClient::settle`] can spend.
/// </param>
/// <param name="spent_by">
/// Transactions that spent the VHTLC, hex, `0x`-prefixed; useful when
/// another device completed the swap.
/// </param>
public record VhtlcAmounts (
    /// <summary>
    /// Spendable by an offchain transaction.
    /// </summary>
    ulong @spendableSats, 
    /// <summary>
    /// Expired outputs that only [`SatoraClient::settle`] can spend.
    /// </summary>
    ulong @recoverableSats, 
    ulong @spentSats, 
    /// <summary>
    /// Transactions that spent the VHTLC, hex, `0x`-prefixed; useful when
    /// another device completed the swap.
    /// </summary>
    string[] @spentBy
) {
}

class FfiConverterTypeVhtlcAmounts: FfiConverterRustBuffer<VhtlcAmounts> {
    public static FfiConverterTypeVhtlcAmounts INSTANCE = new FfiConverterTypeVhtlcAmounts();

    public override VhtlcAmounts Read(BigEndianStream stream) {
        return new VhtlcAmounts(
            @spendableSats: FfiConverterUInt64.INSTANCE.Read(stream),
            @recoverableSats: FfiConverterUInt64.INSTANCE.Read(stream),
            @spentSats: FfiConverterUInt64.INSTANCE.Read(stream),
            @spentBy: FfiConverterSequenceString.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(VhtlcAmounts value) {
        return 0
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.@spendableSats)
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.@recoverableSats)
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.@spentSats)
            + FfiConverterSequenceString.INSTANCE.AllocationSize(value.@spentBy);
    }

    public override void Write(VhtlcAmounts value, BigEndianStream stream) {
            FfiConverterUInt64.INSTANCE.Write(value.@spendableSats, stream);
            FfiConverterUInt64.INSTANCE.Write(value.@recoverableSats, stream);
            FfiConverterUInt64.INSTANCE.Write(value.@spentSats, stream);
            FfiConverterSequenceString.INSTANCE.Write(value.@spentBy, stream);
    }
}





/// <summary>
/// Receive-address tag. Mirrors `lendaswap_sdk::types::Address` — the
/// variant carries both the network and the encoded string so callers
/// can't accidentally pass a Bitcoin address where an Arkade address
/// is required (or vice versa). The SDK's direction validator catches
/// the mismatch but errors are clearer when the type system catches it
/// first.
/// </summary>
public record Address {
    
    public record Arkade (
        string @address
    ) : Address {}
    
    public record Bitcoin (
        string @address
    ) : Address {}
    
    public record Lightning (
        string @invoice
    ) : Address {}
    
    public record Evm (
        string @address
    ) : Address {}
    

    
}

class FfiConverterTypeAddress : FfiConverterRustBuffer<Address>{
    public static FfiConverterRustBuffer<Address> INSTANCE = new FfiConverterTypeAddress();

    public override Address Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new Address.Arkade(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 2:
                return new Address.Bitcoin(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 3:
                return new Address.Lightning(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 4:
                return new Address.Evm(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeAddress.Read()", value));
        }
    }

    public override int AllocationSize(Address value) {
        switch (value) {
            case Address.Arkade variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@address);
            case Address.Bitcoin variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@address);
            case Address.Lightning variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@invoice);
            case Address.Evm variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@address);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeAddress.AllocationSize()", value));
        }
    }

    public override void Write(Address value, BigEndianStream stream) {
        switch (value) {
            case Address.Arkade variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@address, stream);
                break;
            case Address.Bitcoin variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.@address, stream);
                break;
            case Address.Lightning variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@invoice, stream);
                break;
            case Address.Evm variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.@address, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeAddress.Write()", value));
        }
    }
}







/// <summary>
/// How [`SatoraClient::settle`] spent the VHTLC. Txids are hex,
/// `0x`-prefixed.
/// </summary>
public record ArkadeSettlement {
    
    /// <summary>
