/// <summary>
/// Chain identifiers exposed across FFI. Mirrors
/// `lendaswap_sdk::types::Chain` — the underlying SDK type can't carry
/// `#[derive(uniffi::Enum)]` itself (uniffi only derives on types in
/// this crate), so we redefine here and bridge via `From`.
///
/// `Other` is the forward-compat escape hatch: any wire value the SDK
/// doesn't recognise round-trips through it without losing fidelity.
/// </summary>
public record ChainId {
    
    public record Polygon: ChainId {}
    
    
    public record Ethereum: ChainId {}
    
    
    public record Arbitrum: ChainId {}
    
    
    public record Rootstock: ChainId {}
    
    
    public record Arkade: ChainId {}
    
    
    public record Lightning: ChainId {}
    
    
    public record Bitcoin: ChainId {}
    
    
    public record Other (
        string @wire
    ) : ChainId {}
    

    
}

class FfiConverterTypeChainId : FfiConverterRustBuffer<ChainId>{
    public static FfiConverterRustBuffer<ChainId> INSTANCE = new FfiConverterTypeChainId();

    public override ChainId Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new ChainId.Polygon(
                );
            case 2:
                return new ChainId.Ethereum(
                );
            case 3:
                return new ChainId.Arbitrum(
                );
            case 4:
                return new ChainId.Rootstock(
                );
            case 5:
                return new ChainId.Arkade(
                );
            case 6:
                return new ChainId.Lightning(
                );
            case 7:
                return new ChainId.Bitcoin(
                );
            case 8:
                return new ChainId.Other(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeChainId.Read()", value));
        }
    }

    public override int AllocationSize(ChainId value) {
        switch (value) {
            case ChainId.Polygon variant_value:
                return 4;
            case ChainId.Ethereum variant_value:
                return 4;
            case ChainId.Arbitrum variant_value:
                return 4;
            case ChainId.Rootstock variant_value:
                return 4;
            case ChainId.Arkade variant_value:
                return 4;
            case ChainId.Lightning variant_value:
                return 4;
            case ChainId.Bitcoin variant_value:
                return 4;
            case ChainId.Other variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@wire);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeChainId.AllocationSize()", value));
        }
    }

    public override void Write(ChainId value, BigEndianStream stream) {
        switch (value) {
            case ChainId.Polygon variant_value:
                stream.WriteInt(1);
                break;
            case ChainId.Ethereum variant_value:
                stream.WriteInt(2);
                break;
            case ChainId.Arbitrum variant_value:
                stream.WriteInt(3);
                break;
            case ChainId.Rootstock variant_value:
                stream.WriteInt(4);
                break;
            case ChainId.Arkade variant_value:
                stream.WriteInt(5);
                break;
            case ChainId.Lightning variant_value:
                stream.WriteInt(6);
                break;
            case ChainId.Bitcoin variant_value:
                stream.WriteInt(7);
                break;
            case ChainId.Other variant_value:
                stream.WriteInt(8);
                FfiConverterString.INSTANCE.Write(variant_value.@wire, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeChainId.Write()", value));
        }
    }
}







/// <summary>
/// Lightning destination for an Arkade → Lightning swap. The server
/// resolves `Address` / `Lnurl` via LNURL-pay using `sats`, the payout,
/// and the send-max variants using `amount`, the sats the swap takes from
/// Arkade, paying out what remains after fees; `Invoice` carries its
/// amount in the BOLT11 payload.
/// </summary>
public record LightningDestination {
    
    /// <summary>
    /// BOLT11 invoice. Server pays this exact invoice.
    /// </summary>
    public record Invoice (
        string @invoice
    ) : LightningDestination {}
    
    /// <summary>
    /// Lightning address (`user@host`). Server resolves via LUD-16.
    /// </summary>
    public record Address (
        string @address,
        ulong @sats
    ) : LightningDestination {}
    
    /// <summary>
    /// Raw LNURL (`lnurl1…`). Server bech32-decodes + resolves via
    /// LNURL-pay.
    /// </summary>
    public record Lnurl (
        string @lnurl,
        ulong @sats
    ) : LightningDestination {}
    
    /// <summary>
    /// Lightning address with a fixed source amount in sats.
    /// </summary>
    public record AddressSendMax (
        string @address,
        ulong @amount
    ) : LightningDestination {}
    
    /// <summary>
    /// Raw LNURL with a fixed source amount in sats.
    /// </summary>
    public record LnurlSendMax (
        string @lnurl,
        ulong @amount
    ) : LightningDestination {}
    

    
}

class FfiConverterTypeLightningDestination : FfiConverterRustBuffer<LightningDestination>{
    public static FfiConverterRustBuffer<LightningDestination> INSTANCE = new FfiConverterTypeLightningDestination();

    public override LightningDestination Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new LightningDestination.Invoice(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 2:
                return new LightningDestination.Address(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 3:
                return new LightningDestination.Lnurl(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 4:
                return new LightningDestination.AddressSendMax(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 5:
                return new LightningDestination.LnurlSendMax(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeLightningDestination.Read()", value));
        }
    }

    public override int AllocationSize(LightningDestination value) {
        switch (value) {
            case LightningDestination.Invoice variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@invoice);
            case LightningDestination.Address variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@address)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@sats);
            case LightningDestination.Lnurl variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@lnurl)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@sats);
            case LightningDestination.AddressSendMax variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@address)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@amount);
            case LightningDestination.LnurlSendMax variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@lnurl)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@amount);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeLightningDestination.AllocationSize()", value));
        }
    }

    public override void Write(LightningDestination value, BigEndianStream stream) {
        switch (value) {
            case LightningDestination.Invoice variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@invoice, stream);
                break;
            case LightningDestination.Address variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.@address, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@sats, stream);
                break;
            case LightningDestination.Lnurl variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@lnurl, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@sats, stream);
                break;
            case LightningDestination.AddressSendMax variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.@address, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@amount, stream);
                break;
            case LightningDestination.LnurlSendMax variant_value:
                stream.WriteInt(5);
                FfiConverterString.INSTANCE.Write(variant_value.@lnurl, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@amount, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeLightningDestination.Write()", value));
        }
    }
}







